<?php include 'config.php'; $where='WHERE 1'; if(!empty($_GET['search'])){$s=$conn->real_escape_string($_GET['search']);$where.=" AND p.name LIKE '%$s%'";} if(!empty($_GET['category_id'])){$where.=' AND p.category_id='.(int)$_GET['category_id'];} $order='ORDER BY p.product_id DESC'; if(($_GET['sort']??'')==='low')$order='ORDER BY p.price ASC'; if(($_GET['sort']??'')==='high')$order='ORDER BY p.price DESC'; $products=$conn->query("SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON p.category_id=c.category_id $where $order"); $cats=$conn->query("SELECT * FROM categories"); ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Products</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><section class="page"><h1 class="section-title">All Clothes</h1><form class="search-form"><input name="search" placeholder="Search"><select name="category_id"><option value="">All</option><?php while($c=$cats->fetch_assoc()): ?><option value="<?=$c['category_id']?>"><?=clean($c['name'])?></option><?php endwhile; ?></select><select name="sort"><option value="">Sort</option><option value="low">Low to High</option><option value="high">High to Low</option></select><button>Filter</button></form><div class="grid"><?php while($p=$products->fetch_assoc()): ?><div class="card"><img src="<?=clean($p['image_url'])?>"><div class="card-body"><h3><?=clean($p['name'])?></h3><p><?=clean($p['category'])?></p><p class="price">$<?=clean($p['price'])?></p><a class="btn" href="product_detail.php?id=<?=$p['product_id']?>">View Details</a> <a class="btn" href="add_to_cart.php?id=<?=$p['product_id']?>">Add</a></div></div><?php endwhile; ?></div></section><?php include 'footer.php'; ?></body></html>